CREATE TABLE IF NOT EXISTS public.initiatives (id uuid primary key default gen_random_uuid(), key text unique not null, name text not null, tagline text, description text, category text, badge text default 'PATHWAY', sort_order int default 0, is_active boolean default true, created_at timestamptz default now()); ALTER TABLE public.initiatives ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS initiatives_public_read ON public.initiatives; CREATE POLICY initiatives_public_read ON public.initiatives FOR SELECT USING (true);